function makeEffect(sksl: string, n: number) {
  const effect = Skia.RuntimeEffect.Make(sksl);
  if (!effect) throw new Error(`toolbox export: SkSL program ${n} did not compile on this Skia build`);
  return effect;
}

const EFFECT_0 = makeEffect(SKSL_0, 0);

